package org.slavicmyths.client;
import org.slavicmyths.karachun.*;
import net.minecraft.nbt.*;
import net.minecraft.client.model.geom.ModelPart;
import java.util.*;
public final class NightChecks {
 static int checks;static void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 static int uv(ModelPart part)throws Exception{int count=0;var cubes=ModelPart.class.getDeclaredField("cubes");cubes.setAccessible(true);var children=ModelPart.class.getDeclaredField("children");children.setAccessible(true);var polygons=ModelPart.Cube.class.getDeclaredField("polygons");polygons.setAccessible(true);for(var cube:(List<?>)cubes.get(part))for(var poly:(Object[])polygons.get(cube)){var vertices=poly.getClass().getDeclaredField("vertices");vertices.setAccessible(true);for(var v:(Object[])vertices.get(poly)){var u=v.getClass().getDeclaredField("u");var vv=v.getClass().getDeclaredField("v");u.setAccessible(true);vv.setAccessible(true);float x=u.getFloat(v),y=vv.getFloat(v);if(!Float.isFinite(x)||!Float.isFinite(y)||x<0||x>1||y<0||y>1)throw new AssertionError("UV "+x+","+y);count++;}}for(var c:((Map<?,?>)children.get(part)).values())count+=uv((ModelPart)c);return count;}
 public static void main(String[] args)throws Exception{
  check(NightRules.floor(1200)==60,"1200 HP yield floor");for(float hp:new float[]{1200,840,300,61,60})for(float damage:new float[]{0,1,15,10000})check(hp-NightRules.clamp(hp,1200,damage)>=60,"overshoot clamp");
  check(NightRules.phase(841,1200)==1&&NightRules.phase(840,1200)==2&&NightRules.phase(300,1200)==3,"inclusive phase boundaries");for(int n:new int[]{0,24,25,49,50,74,75,100})check(NightRules.tier(n)==(n>=75?3:n>=50?2:n>=25?1:0),"waning tiers");check(NightRules.phantoms(49)==0&&NightRules.phantoms(50)==2&&NightRules.phantoms(74)==2&&NightRules.phantoms(75)==3,"individual phantom cap");check(!NightRules.eligible(0,10000,false)&&NightRules.eligible(1,0,false)&&!NightRules.eligible(0,299,true)&&NightRules.eligible(0,300,true),"AFK and contribution policy");
  var random=new Random(192);int drops=0;for(int i=0;i<10000;i++){double dice=random.nextDouble();var first=NightRules.roll(true,dice,.15);var repeat=NightRules.roll(false,dice,.15);if(first.scythe())drops++;if(!first.wing()||repeat.wing()||first.rune()!=1||first.shard()!=1||repeat.rune()!=1||repeat.shard()!=1||first.scythe()!=repeat.scythe())throw new AssertionError("independent personal reward policy");}check(drops>1350&&drops<1650,"seeded 15% reward distribution");check(!NightRules.roll(false,.15,.15).scythe()&&NightRules.roll(false,.1499,.15).scythe(),"roll boundary");
  UUID player=UUID.randomUUID(),sid=UUID.randomUUID();var root=new CompoundTag();var session=new CompoundTag();session.putUUID("Owner",player);var sessions=new CompoundTag();sessions.put(sid.toString(),session);root.put("Sessions",sessions);var players=new CompoundTag();var progress=new CompoundTag();progress.putBoolean("BlackWingClaimed",true);progress.putInt("Wins",3);var pending=new ListTag();var delivery=new CompoundTag();delivery.putUUID("Delivery",UUID.randomUUID());pending.add(delivery);progress.put("Pending",pending);players.put(player.toString(),progress);root.put("Players",players);var loaded=NightLedger.load(root,null);check(!loaded.activeSessions(),"reload cancels unfinished session");check(loaded.session(sid).getBoolean("Cancelled"),"session cancellation survives load");check(loaded.player(player).getInt("Wins")==3&&loaded.player(player).getBoolean("BlackWingClaimed"),"progression preserved");check(loaded.player(player).getList("Pending",10).size()==1,"durable reward queue preserved");session.putBoolean("Complete",true);var finished=NightLedger.load(root,null);check(finished.session(sid).getBoolean("Complete")&&!finished.session(sid).getBoolean("Cancelled"),"completed session preserved");
  int vertices=uv(KarachunMesh.create())+uv(NightRavenMesh.create());check(vertices==8352,"native cuboid vertex bounds");System.out.println("NIGHT_OFFLINE_PASS checks="+checks+" simulations=10000 nativeUvVertices="+vertices+"; no game launches; NBT is not relog");
 }
}
